import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

const UserGig = () => {
  const { gigId } = useParams();
  const navigate = useNavigate();
  const [gig, setGig] = useState(null);

  useEffect(() => {
    const fetchGig = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/gigs/${gigId}`);
        setGig(res.data);
      } catch (error) {
        console.error("Error fetching gig:", error);
      }
    };

    fetchGig();
  }, [gigId]);

  const handleViewProfile = () => {
    if (gig?.userId) {
      navigate(`/profile/${gig.userId}`);
    } else {
      console.log("User ID is missing from gig data.");
    }
  };

  if (!gig) return <div>Loading...</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "50px auto", padding: "30px", background: "#fff", borderRadius: "12px", boxShadow: "0px 8px 20px rgba(0,0,0,0.08)" }}>
      <h2 style={{ color: "#f97316", textAlign: "center", marginBottom: "24px" }}>GIG POSTING</h2>

      <label><strong>Title</strong></label>
      <input type="text" value={gig.title} disabled style={inputStyle} />

      <label><strong>Gig Type</strong></label>
      <input type="text" value={gig.gigType} disabled style={inputStyle} />

      <label><strong>Genre</strong></label>
      <input type="text" value={Array.isArray(gig.genre) ? gig.genre.join(", ") : gig.genre} disabled style={inputStyle} />

      <label><strong>City</strong></label>
      <input type="text" value={gig.city} disabled style={inputStyle} />

      <label><strong>Description</strong></label>
      <textarea value={gig.description} disabled style={textareaStyle} />

      <label><strong>Date Posted</strong></label>
      <input type="text" value={gig.datePosted?.split("T")[0]} disabled style={inputStyle} />

      <label><strong>Expires</strong></label>
      <input type="text" value={gig.expiryDate?.split("T")[0]} disabled style={inputStyle} />

      <label><strong>Posted By</strong></label>
      <input type="text" value={gig.username} disabled style={inputStyle} />

      <button onClick={handleViewProfile} style={buttonStyle}>
        View User Profile
      </button>
    </div>
  );
};

// 🎨 Styling
const inputStyle = {
  width: "100%",
  padding: "10px",
  margin: "6px 0 12px",
  border: "1px solid #ccc",
  borderRadius: "6px",
  fontSize: "14px"
};

const textareaStyle = {
  ...inputStyle,
  height: "100px",
  resize: "none"
};

const buttonStyle = {
  backgroundColor: "#f97316",
  color: "white",
  width: "100%",
  padding: "12px",
  border: "none",
  borderRadius: "6px",
  fontWeight: "500",
  marginTop: "20px",
  cursor: "pointer"
};

export default UserGig;
